const menuButton = document.querySelector('.menu-toggle');
const navigation = document.querySelector('#main-nav');
function closeMenu() { menuButton.setAttribute('aria-expanded', 'false'); menuButton.setAttribute('aria-label', 'Hap menynë'); navigation.classList.remove('is-open'); }
menuButton.addEventListener('click', () => { const open = menuButton.getAttribute('aria-expanded') !== 'true'; menuButton.setAttribute('aria-expanded', String(open)); menuButton.setAttribute('aria-label', open ? 'Mbyll menynë' : 'Hap menynë'); navigation.classList.toggle('is-open', open); });
navigation.querySelectorAll('a').forEach(link => link.addEventListener('click', closeMenu));
document.addEventListener('keydown', event => { if (event.key === 'Escape' && menuButton.getAttribute('aria-expanded') === 'true') { closeMenu(); menuButton.focus(); } });
window.matchMedia('(min-width: 761px)').addEventListener('change', event => { if (event.matches) closeMenu(); });

const projects = [...document.querySelectorAll('.project')];
document.querySelectorAll('.filter').forEach(button => button.addEventListener('click', () => {
  const category = button.dataset.filter;
  document.querySelectorAll('.filter').forEach(filter => { const active = filter === button; filter.classList.toggle('active', active); filter.setAttribute('aria-pressed', String(active)); });
  let count = 0;
  projects.forEach(project => { const show = category === 'all' || project.dataset.category === category; project.hidden = !show; if (show) { count++; project.classList.add('is-visible'); } });
  document.querySelector('.project-grid').classList.toggle('is-filtered', category !== 'all');
  document.querySelector('#filter-status').textContent = `${count} ${count === 1 ? 'projekt' : 'projekte'}`;
}));

const dialog = document.querySelector('#project-dialog');
let lastProjectButton;
document.querySelectorAll('[data-project]').forEach(button => button.addEventListener('click', () => {
  const data = projectData[button.dataset.project];
  lastProjectButton = button;
  const art = button.querySelector('.project-visual').cloneNode(true);
  art.querySelector('.project-open')?.remove();
  document.querySelector('#dialog-visual').replaceChildren(art);
  const gallery = document.querySelector('#dialog-gallery');
  gallery.replaceChildren();
  gallery.hidden = !data.gallery;
  document.querySelector('#dialog-originals').hidden = !data.originals;
  const resources = document.querySelector('#dialog-resources');
  resources.hidden = !data.pdf;
  if (data.pdf) {
    resources.querySelectorAll('a').forEach(link => link.setAttribute('href', data.pdf.path));
    resources.querySelector('a').firstChild.textContent = `${data.pdf.openLabel} `;
    document.querySelector('#dialog-resource-label').textContent = data.pdf.label;
  }
  document.querySelector('#dialog-credit').textContent = data.credit || 'Projekt konceptual · 2026';
  if (data.gallery) {
    const caption = document.createElement('p');
    caption.className = 'gallery-caption';
    caption.setAttribute('role', 'status');
    const thumbs = document.createElement('div');
    thumbs.className = 'gallery-thumbnails';
    thumbs.setAttribute('role', 'group');
    thumbs.setAttribute('aria-label', data.galleryLabel);
    const selectImage = (item, selectedButton) => {
      const image = document.createElement('img');
      image.src = `${data.assetRoot}/${item.file}`;
      image.alt = item.alt;
      image.width = item.width || 1536;
      image.height = item.height || 1024;
      const figure = document.createElement('figure');
      figure.className = 'hive-gallery-main';
      figure.append(image);
      document.querySelector('#dialog-visual').replaceChildren(figure);
      caption.textContent = item.caption;
      thumbs.querySelectorAll('button').forEach(thumb => { const active = thumb === selectedButton; thumb.setAttribute('aria-pressed', String(active)); });
    };
    data.gallery.forEach((item, index) => {
      const thumb = document.createElement('button');
      thumb.type = 'button';
      thumb.setAttribute('aria-pressed', String(index === 0));
      thumb.setAttribute('aria-controls', 'dialog-visual');
      const image = document.createElement('img');
      image.src = `${data.assetRoot}/${item.file}`;
      image.alt = '';
      image.width = 180;
      image.height = 120;
      const label = document.createElement('span');
      label.textContent = item.label;
      thumb.append(image, label);
      thumb.addEventListener('click', () => selectImage(item, thumb));
      thumbs.append(thumb);
      if (index === 0) selectImage(item, thumb);
    });
    gallery.append(caption, thumbs);
  }
  for (const [id, value] of Object.entries({ 'dialog-title': data.title, 'dialog-category': data.category, 'dialog-description': data.description, 'dialog-idea': data.idea, 'dialog-direction': data.direction })) document.getElementById(id).textContent = value;
  dialog.showModal();
  document.body.classList.add('dialog-open');
  dialog.scrollTop = 0;
  document.querySelector('.dialog-close').focus();
}));
document.querySelector('.dialog-close').addEventListener('click', () => dialog.close());
dialog.addEventListener('click', event => { if (event.target === dialog) { const box = dialog.getBoundingClientRect(); if (event.clientX < box.left || event.clientX > box.right || event.clientY < box.top || event.clientY > box.bottom) dialog.close(); } });
dialog.addEventListener('close', () => { if (!document.querySelector('dialog[open]')) document.body.classList.remove('dialog-open'); lastProjectButton?.focus({ preventScroll: true }); });

// Normal Instagram links remain available when JavaScript is unavailable.
const reelBatchSize = 12;
const reelCollections = {
  koral: { name: 'Koral Secrets Kosova', videos: koralVideos, panel: document.querySelector('#koral-collection'), count: document.querySelector('#reel-count'), more: document.querySelector('#reels-more'), visible: Math.min(reelBatchSize, koralVideos.length) },
  diverse: { name: 'Diverse Academy', videos: diverseVideos, panel: document.querySelector('#diverse'), count: document.querySelector('#diverse-count'), more: document.querySelector('#diverse-more'), visible: Math.min(reelBatchSize, diverseVideos.length) }
};
const reelDialog = document.querySelector('#reel-dialog');
const reelEmbed = document.querySelector('#reel-embed');
const reelClose = document.querySelector('#reel-close');
const reelPrevious = document.querySelector('#reel-previous');
const reelNext = document.querySelector('#reel-next');
let selectedReel = 0;
let selectedReelCollection = 'koral';
let lastReelCard;

function updateReelPage(collection) {
  collection.cards.forEach((card, index) => { card.hidden = index >= collection.visible; });
  collection.count.textContent = `${collection.visible} nga ${collection.videos.length} video`;
  collection.more.hidden = collection.visible >= collection.videos.length;
}

function activateCollection(key) {
  if (!reelCollections[key]) return;
  Object.entries(reelCollections).forEach(([id, collection]) => { collection.panel.hidden = id !== key; });
  document.querySelectorAll('.collection-switcher [data-collection-link]').forEach(link => {
    if (link.dataset.collectionLink === key) link.setAttribute('aria-current', 'true');
    else link.removeAttribute('aria-current');
  });
}

document.querySelectorAll('[data-collection-link]').forEach(link => link.addEventListener('click', event => {
  if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
  // Reveal the target before the browser follows its normal anchor link.
  activateCollection(link.dataset.collectionLink);
}));
function syncCollectionHash() {
  if (location.hash === '#diverse') activateCollection('diverse');
  else if (location.hash === '#reels') activateCollection('koral');
}
activateCollection(location.hash === '#diverse' ? 'diverse' : 'koral');
window.addEventListener('hashchange', syncCollectionHash);
if (location.hash === '#diverse') requestAnimationFrame(() => reelCollections.diverse.panel.scrollIntoView({ block: 'start', behavior: 'instant' }));

function selectReel(key, index) {
  selectedReelCollection = key;
  selectedReel = index;
  const collection = reelCollections[key];
  const video = collection.videos[index];
  const number = String(index + 1).padStart(2, '0');
  document.querySelector('#reel-dialog-brand').textContent = `${collection.name.toUpperCase()} / arber.ai`;
  document.querySelector('#reel-dialog-title').textContent = `VIDEO ${number}`;
  document.querySelector('#reel-dialog-ai').hidden = !video.ai;
  document.querySelector('#reel-position').textContent = `${number} / ${collection.videos.length}`;
  document.querySelector('#reel-instagram').href = video.url;
  reelPrevious.disabled = index === 0;
  reelNext.disabled = index === collection.videos.length - 1;
  const frame = document.createElement('iframe');
  frame.src = `${video.url}embed/`;
  frame.title = `${collection.name} — video ${number}${video.ai ? ' / AI content' : ''} në Instagram`;
  frame.allow = 'autoplay; encrypted-media; picture-in-picture; fullscreen';
  frame.allowFullscreen = true;
  frame.referrerPolicy = 'strict-origin-when-cross-origin';
  reelEmbed.replaceChildren(frame);
}

Object.entries(reelCollections).forEach(([key, collection]) => {
  collection.cards = [...collection.panel.querySelectorAll('[data-reel]')];
  updateReelPage(collection);
  collection.more.addEventListener('click', () => {
    const firstNewIndex = collection.visible;
    collection.visible = Math.min(collection.visible + reelBatchSize, collection.videos.length);
    updateReelPage(collection);
    collection.cards[firstNewIndex]?.focus({ preventScroll: true });
    collection.cards[firstNewIndex]?.scrollIntoView({ block: 'start', behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth' });
  });
  collection.cards.forEach(card => card.addEventListener('click', event => {
    if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
    const index = collection.videos.findIndex(video => video.id === card.dataset.reel);
    if (index === -1) return;
    event.preventDefault();
    lastReelCard = card;
    selectReel(key, index);
    reelDialog.showModal();
    document.body.classList.add('dialog-open');
    reelDialog.scrollTop = 0;
    reelClose.focus();
  }));
});
reelPrevious.addEventListener('click', () => { if (selectedReel > 0) selectReel(selectedReelCollection, selectedReel - 1); });
reelNext.addEventListener('click', () => { if (selectedReel < reelCollections[selectedReelCollection].videos.length - 1) selectReel(selectedReelCollection, selectedReel + 1); });
reelClose.addEventListener('click', () => reelDialog.close());
reelDialog.addEventListener('click', event => {
  if (event.target !== reelDialog) return;
  const box = reelDialog.getBoundingClientRect();
  if (event.clientX < box.left || event.clientX > box.right || event.clientY < box.top || event.clientY > box.bottom) reelDialog.close();
});
reelDialog.addEventListener('close', () => {
  reelEmbed.replaceChildren();
  if (!document.querySelector('dialog[open]')) document.body.classList.remove('dialog-open');
  lastReelCard?.focus({ preventScroll: true });
});

if ('IntersectionObserver' in window && !window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
  const observer = new IntersectionObserver(entries => entries.forEach(entry => { if (entry.isIntersecting) { entry.target.classList.add('is-visible'); observer.unobserve(entry.target); } }), { threshold: 0.08 });
  document.querySelectorAll('.reveal').forEach(element => { element.classList.add('will-reveal'); observer.observe(element); });
}
